!function(){"use strict";(window.PNTT=window.PNTT||{}).NPC_DAO_LY={tho_ren:["Sắt chịu lửa mới thành binh khí; người chịu thử thách mới biết mình cứng ở đâu.","Một nhát búa lệch có thể làm hỏng cả thanh kiếm. Một niệm lệch cũng vậy.","Đừng chỉ mài lưỡi kiếm; hãy mài cả tính khí của người cầm kiếm.","Pháp bảo tốt không cứu nổi chủ nhân hấp tấp. Tay vững thì vật thường cũng thành lợi khí.","Lửa rèn không hỏi ngươi là ai, chỉ hỏi ngươi có chịu tôi luyện đến cùng hay không."],van_bao_phuong:["Vạn Bảo Phường không bán rẻ, cũng không mua hớ — giá là do người tu định.","Treo hàng không mất xu nào; bán được thì lão chỉ giữ một phần mười làm phí.","Món nào treo quá hai ngày không ai hỏi, lão tự gửi trả về túi người bán.","Pháp bảo trong túi mà không dùng tới thì chỉ là cục sắt; lên chợ nó mới thành Linh Thạch.","Của đã khoá bằng thần niệm thì lão không nhận treo — đồ quý thì tự giữ lấy."],ba_hang_com:["Người tu có thể nhịn đói vài ngày, nhưng đừng để cái bụng rỗng làm loạn đạo tâm.","Một bữa cơm nóng giữ được lòng người lâu hơn mấy viên linh thạch lạnh tanh.","Đạo lớn nằm trong trời đất, đạo nhỏ nằm trong cách ngươi đối đãi với người nấu cơm.","Ăn đủ, ngủ yên, tâm không vướng; đó cũng là một nửa công phu tu luyện.","Có ngày phải tranh cơ duyên, có ngày chỉ cần ngồi xuống ăn cùng nhau là đủ hóa giải hiềm khích."],tieu_nhi_luan_vo:["Lên đài bụng đói thì thua trước khi rút kiếm. Một bát cơm đi!","Phù hộ thân, phù hồi khí — có cả. Mua trước khi trọng tài gọi tên.","Kỳ nào cũng có người lên bia. Kỳ này tới lượt ai đây?","Cơm mang theo lên đài vẫn nóng, ta bọc lá sen cả rồi.","Thắng hay thua cũng ghé lại quầy, bát trà nóng không tính tiền."],su_phu:["Linh lực là dòng nước, tâm cảnh là lòng sông; lòng sông hẹp thì nước mạnh cũng thành tai họa.","Cảnh giới tăng nhanh chưa chắc là phúc. Căn cơ không vững, gió lớn sẽ làm cây bật rễ.","Học pháp trước hết học cách giữ mạng, sau đó mới học cách thắng người.","Kẻ địch đáng sợ nhất không ở ngoài kia, mà là niệm tham thắng đang nổi trong lòng mình.","Con đường tu tiên không hứa cho ngươi bình an; nó chỉ dạy ngươi đủ sáng suốt để bước qua bất an.","Khi không biết chọn đường, hãy chọn việc đúng trước việc có lợi. Đạo tâm sẽ tự chỉ lối."],huyet_anh_khach:["Trong thiên hạ này, kẻ yếu chỉ có một lỗi: tin rằng lòng thương của kẻ mạnh là thật.","Đạo lý là chiếc áo người ta khoác lên quyền lực để thiên hạ bớt sợ.","Muốn đứng trên đầu người khác, trước hết phải quen với việc không ai chìa tay kéo ngươi lên.","Kẻ thắng viết lịch sử, kẻ thua viết di ngôn; bản tọa chỉ quan tâm ai còn đứng cuối cùng.","Máu không làm người mạnh hơn. Nhưng kẻ dám nhìn thẳng vào máu của mình thường sống lâu hơn."],chap_su_dai_hoi:["Luật lệ không làm người mạnh yếu đi; luật lệ chỉ ngăn kẻ mạnh biến cuộc đấu thành trò giết chóc.","Trước khi bước vào đại hội, hãy biết mình muốn chứng minh điều gì và sẵn sàng mất điều gì.","Một trận thắng đẹp là thắng bằng bản lĩnh, không phải bằng việc chờ đối thủ sơ suất mãi.","Danh tiếng đến từ một lần bùng sáng, còn uy tín đến từ trăm lần giữ đúng lời.","Biết nhận thua đúng lúc cũng là một loại thần thông bảo toàn đạo thống.","Người dự đại hội nên mang theo kiếm, tâm bình và một đôi mắt biết nhìn rộng hơn bảng xếp hạng."],tang_kinh_lao_nhan:["Đọc một vạn quyển không bằng hiểu một câu, nhưng muốn hiểu một câu thường phải đọc rất nhiều.","Bí pháp quý không nằm ở chữ cuối cùng, mà ở chỗ ngươi nhận ra điều gì còn bị giấu giữa các dòng.","Kẻ chép được pháp quyết chưa chắc chép được đạo tâm của người sáng lập pháp quyết ấy.","Kiến thức không làm ngươi cao quý hơn; cách ngươi dùng nó để đối đãi với kẻ chưa biết mới quyết định điều đó.","Có sách chỉ nên mở khi đủ cảnh giới, không phải vì giấy biết giận, mà vì người đọc chưa đủ sức gánh hậu quả.","Tàng kinh các rộng đến đâu cũng không rộng bằng một tâm trí chịu học hỏi."],manh_shopt1:["Sáng nào ghé chỗ ta một lần, linh thạch lộ phí ta phát đủ.","Đường tu dài lắm, nhưng bước đầu mỗi ngày thì ngắn thôi: điểm danh.","Dựng game cũng như tu đạo, mỗi ngày tiến một chút, đừng bỏ giữa chừng.","Có chỗ nào trong cõi này chưa vừa ý, cứ nói. Ta nghe.","Giơ ngón cái cho đạo hữu đó. Đi tu tiếp nào!"],ly_thanh:["Trúc càng cao càng biết cúi theo gió; người càng mạnh càng phải biết nhường đúng lúc.","Đừng coi thường yêu thú nhỏ. Rừng sâu giữ mạng bằng những điều tưởng như vụn vặt.","Kiếm pháp tốt giúp ngươi thắng một trận, còn biết nghe tiếng lá giúp ngươi sống qua cả khu rừng.","Đánh quái một mình là luyện lực, phối hợp cùng đồng môn mới là luyện đạo.","Mỗi dấu chân trên đất đều kể một câu chuyện; người tuần rừng giỏi phải học cách đọc chúng.","Gió trong rừng không đứng về phía ai. Muốn đi xa, hãy học cách bước cùng nó."],dai_phu:["Dược liệu không có thiện ác; đúng liều là thuốc, quá tay là độc.","Cứu một mạng cần tay nghề, cứu được lòng người cần thêm sự kiên nhẫn.","Người luyện đan hay quên nhất một điều: cơ thể cũng là một lò luyện, đừng đốt nó quá lửa.","Vết thương nói thật hơn lời khoe khoang; nhìn khí sắc rồi mới nghe lời bệnh nhân.","Sinh cơ giống mầm cây, ép nó lớn quá nhanh chỉ khiến rễ không bám được vào đất.","Kẻ biết dùng độc chưa đáng sợ bằng kẻ không biết mình đang trúng độc."],lao_dao_hang_cave:["Cửa hang không hỏi ngươi can đảm đến đâu, nó chỉ cho ngươi thấy mình còn chưa biết gì.","Người biết quay đầu trước vực sâu không phải kẻ hèn; đó là người còn muốn đi tiếp.","Trong bí cảnh, một tiếng động nhỏ cũng có thể là lời cảnh báo cuối cùng của thiên nhiên.","Cảnh giới cao mở được cửa đá, nhưng tâm cảnh vững mới giúp ngươi tìm được đường về.","Đừng mang lòng tham bước vào nơi chưa hiểu rõ. Bí bảo nào cũng có cái giá của nó.","Ta đi nhiều năm mới hiểu: đường xa không đáng sợ bằng việc không biết vì sao mình đang đi."],ong_tu_mieu:["Hương khói không làm thần linh no, chỉ nhắc người sống nhớ mình từ đâu mà có.","Nước trong hồ này chảy ra từ lòng núi. Uống thì nhớ nguồn, tu thì nhớ gốc.","Quét sân miếu mỗi sáng cũng là tu. Lá hôm nay rụng, mai lại rụng; tâm không được bực.","Người cầu xin thì nhiều, người cảm tạ thì ít. Lão chỉ mong khách tới đây biết cúi đầu một lần.","Tu vi cao mà lòng hẹp, cũng như đỉnh hương đẹp mà trong không có nén nhang nào.","Ông Trường Con không để lại pháp quyết nào — chỉ để lại một mạch nước. Thế mà làng này sống nhờ nó cả trăm năm."],nu_tu_mieu_hoang:["Miếu có thể hoang, nhưng lời nguyện đã gieo thì vẫn còn người nghe thấy.","Hương tàn không có nghĩa là thần linh rời đi; đôi khi chỉ là lòng người đã quên cúi đầu.","Người tu không nên sợ bóng tối, chỉ nên sợ mình đem bóng tối ấy nuôi trong tâm.","Một nén hương thành kính quý hơn trăm lễ vật dâng bằng lòng tham.","Kẻ đã khuất không cần ngươi thương hại; họ chỉ mong người sống đừng lặp lại sai lầm của họ.","Giữ một ngọn đèn trong đêm cũng là giữ một phần nhân tính giữa cõi tu hành."],tgt_thien_kiem_tong:["Kiếm tu không lấy mũi kiếm làm đầu, mà lấy một niệm thẳng làm đầu.","Một kiếm đã xuất thì không nên hỏi gió có thuận hay không.","Muốn kiếm sắc, trước hết phải để tâm mình bớt quanh co.","Kiếm không chỉ để thắng địch; nó còn để che chở người không có kiếm.","Cường giả thật sự biết thu kiếm trước khi sát ý biến thành nghiệp.","Đường kiếm càng ngắn, quyết tâm càng phải sâu."],tgt_thanh_van_mon:["Mây không giữ một hình dạng, nên mới đi được qua muôn ngọn núi.","Tu sĩ Thanh Vân học cách mượn thế trời, không cố dùng sức mình chống lại mọi cơn gió.","Tầm mắt hẹp thì một bậc thềm cũng thành vách núi; tâm rộng thì vách núi cũng có đường qua.","Đừng bám chặt vào một thắng lợi. Gió đổi hướng rồi, người cũng phải biết đổi thế.","Tự do không phải muốn làm gì thì làm, mà là đủ sáng suốt để không bị dục vọng kéo đi.","Mây cao vì nhẹ; người tiến xa cũng phải biết bỏ bớt thứ đang níu chân mình."],tgt_truong_sinh_coc:["Trường sinh không chỉ là sống lâu, mà là mỗi ngày sống có thêm ý nghĩa.","Cây cổ thụ không lớn nhờ một trận mưa; đạo hạnh cũng không thành nhờ một lần đột phá.","Biết chữa lành cho người khác là học cách nhìn thấy phần yếu mềm của chính mình.","Sinh cơ đi vòng như rễ cây, chậm nhưng bền; đừng ép đạo của mình phải nở hoa trong một đêm.","Người giữ được một mầm sống giữa loạn thế đã thắng một trận lớn hơn nhiều cuộc tranh danh.","Vạn vật đều có lúc suy tàn, nên người hiểu trường sinh càng phải biết trân trọng hiện tại."],tgt_van_phu_cac:["Một nét phù là hình, một nét tâm là ý; thiếu một trong hai thì chỉ là mực trên giấy.","Phù chú giỏi không cần ồn ào. Đến khi địch nhận ra, kết quả thường đã định.","Người vẽ phù phải giữ tay ổn như giữ lời thề, sai một nét là đổi cả thiên cơ.","Chuẩn bị trước không phải nhát gan; đó là cách phù tu thắng trận trước khi giao chiến.","Linh lực có thể cạn, nhưng người hiểu trận thế luôn tìm được một nét cuối cùng để xoay chuyển.","Mỗi lá phù là một lời hứa với trời đất, đừng dùng nó cho chuyện không đáng."],tgt_dai_la_phat_tong:["Thân như núi không phải để đè người, mà để người phía sau có chỗ nương tựa.","Lực lớn mà tâm nóng thì chỉ là tảng đá lăn xuống dốc.","Kim cang hộ pháp trước hết hộ được niệm sân trong chính mình.","Chịu được một đòn chưa phải mạnh; biết vì sao mình chịu đòn mới là có căn cơ.","Từ bi không làm nắm đấm yếu đi, nó chỉ khiến nắm đấm biết dừng đúng lúc.","Người luyện thân nên nhớ: xương cứng đến đâu cũng cần một đạo tâm mềm để không gãy."],tgt_ngu_thu_tong:["Thuần phục một linh thú không bằng giành được lòng tin của nó.","Thú nghe được mùi sợ hãi; tâm loạn thì linh thú cũng loạn theo.","Đừng gọi bạn đồng hành là chiến lợi phẩm. Kẻ khinh nó rồi sẽ bị nó bỏ lại.","Mỗi loài có một cách nói riêng: tiếng gầm, dấu chân và cả sự im lặng.","Người ngự thú giỏi không kéo linh thú chạy theo mình, mà cùng nó tìm một hướng đi.","Muốn cưỡi gió cùng mãnh thú, trước hết phải học cách không phản bội lời hứa."],tgt_dieu_am_mon:["Âm luật bắt đầu từ hơi thở; hơi thở loạn thì tiếng đàn cũng không cứu nổi tâm.","Một nốt đúng lúc có thể lay động người hơn trăm lời tranh luận.","Diệu Âm không chỉ nghe tiếng vang, mà nghe cả khoảng lặng sau tiếng vang ấy.","Lời nói là pháp khí mềm nhất: có thể mở lòng người, cũng có thể cắt sâu hơn kiếm.","Muốn điều khiển tiếng động, hãy học cách giữ im lặng trước khi cất tiếng.","Khúc nhạc hay không ép người khác phải khóc; nó chỉ khiến họ tự nhớ điều từng đánh mất."],ma_dao_hop_hoan_tong:["Dục niệm không đáng sợ; đáng sợ là kẻ tưởng mình đã làm chủ nó nhưng chưa từng soi vào lòng.","Mộng có thể khóa người khác, nhưng tâm mình mới là chiếc lồng khó phá nhất.","Kẻ quyến rũ được thiên hạ chưa chắc quyến rũ nổi cô độc của chính mình.","Tình cảm là linh lực mềm, dùng đúng thì nối duyên, dùng sai thì trói cả hai người.","Muốn đọc được lòng người, trước hết phải dám nhìn thẳng vào điều mình đang ham muốn.","Một nụ cười có thể hóa giải sát khí, cũng có thể che giấu một lưỡi dao."],ma_dao_quy_linh_mon:["Quỷ linh không sinh ra để hầu hạ; nó chỉ đi theo kẻ đủ gan nhìn thẳng vào nỗi sợ.","Gọi được một hồn ma dễ hơn giữ cho thần trí mình không vỡ vụn.","Người chết có thể im lặng, nhưng oán niệm của họ chưa bao giờ câm.","Thần thức yếu mà đòi điều khiển u linh khác nào cầm đuốc đi vào kho thuốc nổ.","Kẻ tu quỷ đạo phải biết tôn trọng cái chết, nếu không sớm muộn cũng thành thứ bị người khác gọi tên.","Có những bóng ma chỉ muốn được siêu thoát, đừng biến mọi tiếng khóc thành chiến lợi phẩm."],ma_dao_co_doc_tong:["Độc đáng sợ nhất không có màu, không mùi và thường được trao bằng một nụ cười.","Một giọt độc đúng chỗ thắng cả bình độc đổ bừa; tu độc là học sự chính xác.","Người luyện độc phải thuộc lòng giải dược, vì cơ thể mình luôn là người thử đầu tiên.","Độc tính tăng chậm mới khiến đối thủ quên mất mình đang chết.","Lòng tham cũng có độc, chỉ là không có thầy thuốc nào bán thuốc giải cho nó.","Biết làm hại người là bản lĩnh thấp; biết dừng tay trước khi độc lan sang mình mới là tu vi."],ma_dao_thien_sat_tong:["Sát ý là lửa, đốt được địch nhưng cũng thiêu sạch người giữ nó.","Kẻ chỉ biết tiến sẽ chết vì không biết lúc nào nên thu đao.","Thương thế không làm ngươi mạnh; cách ngươi đứng dậy sau thương thế mới làm được điều đó.","Cuồng sát có thể thắng một khoảnh khắc, nhưng kỷ luật mới thắng được một đời.","Đừng nhầm tiếng tim đập nhanh với dũng khí; đôi khi đó chỉ là nỗi sợ đang mặc áo đỏ.","Muốn chém xuyên phòng thủ của người khác, trước hết phải phá được sự hỗn loạn trong tâm mình."],ma_dao_thien_thi_tong:["Thi thể giữ được hình hài, nhưng không giữ được nhân tính nếu người điều khiển đã quên giới hạn.","Âm khí lạnh không đáng sợ bằng một trái tim đã quen xem người sống như vật liệu.","Người mượn sức tử thi phải trả giá bằng sự cô độc của kẻ không còn được người sống tin.","Cái chết không phải cánh cửa để tùy tiện mở ra đóng vào theo ý một kẻ luyện công.","Thi hóa cho thân cứng hơn, nhưng đạo tâm mà hóa đá thì chẳng còn gì để bảo vệ.","Đừng gọi sự bất tử là trường sinh khi trong lòng ngươi đã không còn một phần nào muốn sống."],ma_dao_hac_nhai_dao:["Bóng tối không làm người ta vô hình; chỉ có sự kiên nhẫn mới khiến bước chân không bị nghe thấy.","Ẩn sát là một lần chờ đợi đổi lấy một lần xuất thủ, đừng phí nó vào cơn giận.","Kẻ lộ tâm trước khi lộ thân đã thua nửa trận.","Đường lui không phải dấu hiệu thất bại; nó là thứ giúp ngươi có ngày trở lại.","Một đòn đúng thời điểm quý hơn mười đòn nhanh mà không có chủ ý.","Nhai đen dạy rằng mọi cái bóng đều có chủ nhân; muốn thoát bóng, phải thắng chính mình."],tong_mon_quan_su:["Tông môn không lớn nhờ cờ hiệu cao, mà nhờ từng đệ tử chịu làm những việc không ai nhìn thấy.","Sổ công lao chép đủ cả việc nhỏ: một bó cá, một túi quặng, đều là gạch xây sơn môn.","Tông Môn Chiến thắng thua một đêm, nhưng tông nào ghi danh đều đã thắng được sự lười biếng.","Chưởng môn mạnh thì tông mạnh một đời; đệ tử đồng lòng thì tông mạnh nhiều đời.","Linh thạch vào quỹ chung không mất đi đâu cả, nó chỉ đổi chỗ từ túi một người sang vai cả tông.","Lão chỉ giữ sổ, còn danh tiếng của tông môn là do chính các ngươi viết nên mỗi ngày."],tran_phap_su:["Trận pháp không sinh ra để thay người tu luyện, nó chỉ khuếch đại điều đã có trong tâm.","Một viên đá lệch chỗ đủ làm cả đại trận mất cân bằng; một người sai vị trí cũng vậy.","Muốn phá trận, hãy tìm mạch khí chứ đừng chỉ đập vào bức tường trước mặt.","Trận bàn mạnh nhờ liên kết, người tu cũng mạnh nhờ biết đứng đúng cạnh đồng đạo.","Thiên cơ không miễn phí: trận vận chuyển đi xa đến đâu, linh thạch duy trì cũng phải theo đến đó.","Kẻ hiểu trận pháp nhìn thấy đường đi trong hỗn loạn, còn kẻ hấp tấp chỉ thấy thêm một cái bẫy."]}}();